import tensorflow as tf
@tf.custom_gradient
def custom_op(x):
    def grad(dy):
        return dy * 2.0
    return x ** 2, grad
x = tf.Variable(3.0)
with tf.GradientTape() as tape:
    y = custom_op(x)
print(tape.gradient(y, x).numpy())

