import tensorflow as tf
@tf.function
def dynamic_control_flow(x, n):
    total = tf.constant(0)
    for i in tf.range(n):
        if tf.reduce_sum(x) > 0:
            total += i
        else:
            total -= i
    return total
print(dynamic_control_flow(tf.constant([1.0, 2.0]), tf.constant(4)))

import tensorflow as tf
class CustomGradLayer(tf.keras.layers.Layer):
    @tf.custom_gradient
    def call(self, x):
        def grad(dy):
            return dy * 3.0
        return x ** 2, grad
layer = CustomGradLayer()
x = tf.Variable([[2.0, 3.0]])
with tf.GradientTape() as tape:
    y = layer(x)
print(tape.gradient(y, x).numpy())

