import tensorflow as tf
class DynamicLayer(tf.keras.layers.Layer):
    def call(self, inputs, training=None):
        if training:
            return tf.nn.dropout(inputs, rate=0.5)
        return inputs
layer = DynamicLayer()
print(layer(tf.ones((2, 4)), training=True).shape)

import tensorflow as tf
@tf.function
def nested_cond(x):
    if tf.reduce_sum(x) > 0:
        if x[0] > 0:
            return x * 2
        else:
            return x * 3
    else:
        return x * 4
print(nested_cond(tf.constant([1.0, -2.0])))
